     1	//! Equivalence of `src/util/ctype_compat.h`'s eight macros with their ports.
     2	//!
     3	//! On this build each macro's replacement list is `<ctype.h>`'s function over its argument
     4	//! cast to `unsigned char`, as `!!isalpha((unsigned char)(a))`. The raw bindings reach no
     5	//! macro, so each is compared twice:
     6	//!
     7	//! - with its replacement list, glibc's function called on the byte the cast gives, for every `int`
     8	//!   from below `CHAR_MIN` to past `UCHAR_MAX`: `EOF`, the negative `char`s a signed `char` holds
     9	//!   and the `int`s the cast reduces. Neither the raw bindings nor `glibc-bindings` bind
    10	//!   `<ctype.h>`, so its eight functions are declared here, as glibc exports them; and
    11	//! - where the C expands it, through the functions whose result a single byte's class decides:
    12	//!   `git__isspace` through `git_blob_data_is_binary` (`git_str_is_binary`, for the control bytes
    13	//!   it does not count as printable) and `git_config_parse_int64` (`git__strntol64`'s leading white
    14	//!   space), and `git__isalnum` through `git_message_trailers` (a trailer key's characters).
    15	//!
    16	//! The other sites are not reached through a function the bindings give a single byte to:
    17	//! `git__isalpha`, `git__isdigit` and `git__toupper` expand in `date.c`'s parser, which
    18	//! libgit2 runs on a commit's date from the environment, `git__isprint` and `git__isxdigit`
    19	//! in `smart_pkt.c`'s `parse_len` and `str.c`'s `git_str_decode_percent`, which no bound
    20	//! function calls, and `git__tolower` in case-insensitive comparisons of whole names. Their
    21	//! comparison with the replacement list covers every argument those sites can pass.
    22	//!
    23	//! The test process never calls `setlocale`, so `<ctype.h>` runs in the C locale, as in
    24	//! libgit2.
    25	
    26	use std::ffi::{CString, c_int};
    27	
    28	use libgit2_crustify::libgit2::src::libgit2::blob::data_is_binary;
    29	use libgit2_crustify::libgit2::src::libgit2::config::parse_i64;
    30	use libgit2_crustify::libgit2::src::libgit2::trailer::MessageTrailerArray;
    31	use libgit2_crustify::libgit2::src::util::ctype_compat_h::{
    32	    is_alnum, is_alpha, is_digit, is_print, is_space, is_xdigit, to_lower, to_upper,
    33	};
    34	
    35	unsafe extern "C" {
    36	    fn isalnum(c: c_int) -> c_int;
    37	    fn isalpha(c: c_int) -> c_int;
    38	    fn isdigit(c: c_int) -> c_int;
    39	    fn isprint(c: c_int) -> c_int;
    40	    fn isspace(c: c_int) -> c_int;
    41	    fn isxdigit(c: c_int) -> c_int;
    42	    fn tolower(c: c_int) -> c_int;
    43	    fn toupper(c: c_int) -> c_int;
    44	}
    45	
    46	/// `(unsigned char)(a)`: the low byte of `a`'s two's complement.
    47	fn as_unsigned_char(a: c_int) -> u8 {
    48	    a.to_le_bytes()[0]
    49	}
    50	
    51	/// `f((unsigned char)(a))`, as the macro's replacement list calls it.
    52	fn c_call(f: unsafe extern "C" fn(c_int) -> c_int, a: c_int) -> c_int {
    53	    // SAFETY: `<ctype.h>`'s functions are defined for every value of `unsigned char` and for
    54	    // `EOF`, read only the calling thread's locale tables, and keep nothing; the cast makes the
    55	    // argument an `unsigned char`'s value.
    56	    unsafe { f(c_int::from(as_unsigned_char(a))) }
    57	}
    58	
    59	/// Every `int` the comparison passes: below `CHAR_MIN`, through every `char` and byte value,
    60	/// and past `UCHAR_MAX`.
    61	fn arguments() -> impl Iterator<Item = c_int> {
    62	    -300..=600
    63	}
    64	
    65	#[test]
    66	#[cfg_attr(miri, ignore = "calls C")]
    67	fn the_predicates_match_the_replacement_lists() {
    68	    type Pair = (
    69	        &'static str,
    70	        fn(u8) -> bool,
    71	        unsafe extern "C" fn(c_int) -> c_int,
    72	    );
    73	    let pairs: [Pair; 6] = [
    74	        ("git__isalnum", is_alnum, isalnum),
    75	        ("git__isalpha", is_alpha, isalpha),
    76	        ("git__isdigit", is_digit, isdigit),
    77	        ("git__isprint", is_print, isprint),
    78	        ("git__isspace", is_space, isspace),
    79	        ("git__isxdigit", is_xdigit, isxdigit),
    80	    ];
    81	    for (name, rust, c) in pairs {
    82	        for a in arguments() {
    83	            // `!!f(...)`: the C normalises the class to 0 or 1.
    84	            let c_class = c_call(c, a) != 0;
    85	            assert_eq!(rust(as_unsigned_char(a)), c_class, "{name}({a})");
    86	        }
    87	    }
    88	}
    89	
    90	#[test]
    91	#[cfg_attr(miri, ignore = "calls C")]
    92	fn the_case_maps_match_the_replacement_lists() {
    93	    type Pair = (
    94	        &'static str,
    95	        fn(u8) -> u8,
    96	        unsafe extern "C" fn(c_int) -> c_int,
    97	    );
    98	    let pairs: [Pair; 2] = [
    99	        ("git__tolower", to_lower, tolower),
   100	        ("git__toupper", to_upper, toupper),
   101	    ];
   102	    for (name, rust, c) in pairs {
   103	        for a in arguments() {
   104	            let mapped = rust(as_unsigned_char(a));
   105	            assert_eq!(c_int::from(mapped), c_call(c, a), "{name}({a})");
   106	        }
   107	    }
   108	}
   109	
   110	/// `git_str_is_binary` counts a byte as printable above `0x1F` but for DEL, and for `\b`,
   111	/// ESC and the form feed; of the others, a NUL makes the data binary, and any byte
   112	/// `git__isspace` rejects counts against it. A single byte of those is binary exactly when it
   113	/// is not white space.
   114	#[test]
   115	#[cfg_attr(miri, ignore = "calls libgit2")]
   116	fn is_space_matches_git_str_is_binary() {
   117	    for c in u8::MIN..=u8::MAX {
   118	        let printable = (c > 0x1F && c != 0x7F) || matches!(c, 0x08 | 0x1B | 0x0C);
   119	        let expected = c == 0 || (!printable && !is_space(c));
   120	        assert_eq!(data_is_binary(&[c]), expected, "{c:#04x}");
   121	    }
   122	}
   123	
   124	/// `git__strntol64` skips the white space `git__isspace` finds before the number:
   125	/// `<c><c>7` reads as 7 exactly when `c` is white space, or the octal prefix `0`.
   126	#[test]
   127	#[cfg_attr(miri, ignore = "calls libgit2")]
   128	fn is_space_matches_git_config_parse_int64() {
   129	    for c in 1..=u8::MAX {
   130	        let value = CString::new([c, c, b'7']).expect("no NUL");
   131	        let seven = parse_i64(Some(&value)).ok() == Some(7);
   132	        assert_eq!(seven, is_space(c) || c == b'0', "{c:#04x}");
   133	    }
   134	}
   135	
   136	/// A trailer key is read while `git__isalnum` or `-` accepts its characters: `K<c>y: v` is
   137	/// the trailer `K<c>y` exactly when `c` is a letter, a digit or `-`.
   138	#[test]
   139	#[cfg_attr(miri, ignore = "calls libgit2")]
   140	fn is_alnum_matches_git_message_trailers() {
   141	    for c in 1..=u8::MAX {
   142	        let mut message = b"Subject\n\nK".to_vec();
   143	        message.extend_from_slice(&[c, b'y', b':', b' ', b'v', b'\n']);
   144	        let message = CString::new(message).expect("no NUL");
   145	        let array = MessageTrailerArray::parse(&message).expect("git_message_trailers");
   146	        let trailers: Vec<_> = array
   147	            .as_ref()
   148	            .trailers()
   149	            .iter()
   150	            .map(|t| (t.key().to_bytes().to_vec(), t.value().to_bytes().to_vec()))
   151	            .collect();
   152	        let is_key = trailers == [(vec![b'K', c, b'y'], b"v".to_vec())];
   153	        assert_eq!(is_key, is_alnum(c) || c == b'-', "{c:#04x}");
   154	    }
   155	}
